WITH valid AS (SELECT id, method, paid_at, status, CEIL(amount) AS amount_whole, LENGTH(status) AS status_length FROM payments WHERE order_id IS NOT NULL), with_prev AS (SELECT *, LAG(paid_at) OVER (PARTITION BY method ORDER BY paid_at, id) AS prev_paid_at FROM valid), with_gaps AS (SELECT *, CASE WHEN prev_paid_at IS NULL OR paid_at > prev_paid_at + INTERVAL 14 DAYS THEN 1 ELSE 0 END AS is_new_burst FROM with_prev), islands AS (SELECT id, method, paid_at, status, amount_whole, status_length, SUM(is_new_burst) OVER (PARTITION BY method ORDER BY paid_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS burst_id FROM with_gaps), with_gaps_2 AS (SELECT *, CASE WHEN LAG(paid_at) OVER (PARTITION BY status ORDER BY paid_at, id) IS NULL OR paid_at > LAG(paid_at) OVER (PARTITION BY status ORDER BY paid_at, id) + INTERVAL '7' DAY THEN 1 ELSE 0 END AS is_new_session FROM islands), sessionized AS (SELECT *, SUM(is_new_session) OVER (PARTITION BY status ORDER BY paid_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS island_id FROM with_gaps_2), matched_keys AS (SELECT id FROM sessionized INTERSECT ALL SELECT id FROM payments WHERE method IS NOT NULL), verified AS (SELECT s.* FROM sessionized s JOIN matched_keys k ON s.id = k.id), metrics AS (SELECT *, DENSE_RANK() OVER (PARTITION BY DATE_TRUNC('month', paid_at), method ORDER BY is_new_session NULLS FIRST) AS is_new_session_dense_rank, SUM(island_id) OVER w_running AS island_id_sum_90d, MAX(burst_id) OVER (PARTITION BY method) AS method_max_burst_id, MIN(status_length) OVER (PARTITION BY status, method) AS status_min_status_length FROM verified WINDOW w_running AS (ORDER BY CAST(paid_at AS BIGINT) RANGE BETWEEN 7776000 PRECEDING AND CURRENT ROW)) SELECT method, paid_at, status, amount_whole, status_length, island_id, island_id_sum_90d, status_min_status_length, CASE WHEN status RLIKE '^(FAILED|REFUNDED)$' THEN 'GROUP_A' ELSE 'EXTENDED' END AS status_zone FROM metrics ORDER BY island_id
